package client

import (
	"context"
	"errors"

	"github.com/cloudwego/kitex/pkg/endpoint/cep"
	"github.com/cloudwego/kitex/pkg/rpcinfo"
	"github.com/cloudwego/kitex/pkg/streaming"
)

// StreamClient provides stream-aware client APIs with endpoint middleware support.
// It integrates with pkg/streaming types and pkg/endpoint/cep for client-side streaming.
type StreamClient interface {
	// ServerStreaming initiates a server-streaming RPC call.
	// The client sends a single request and receives a stream of responses.
	ServerStreaming(ctx context.Context, method string, req interface{}) (streaming.ServerStreamingClient, error)

	// ClientStreaming initiates a client-streaming RPC call.
	// The client sends a stream of requests and receives a single response.
	ClientStreaming(ctx context.Context, method string) (streaming.ClientStreamingClient, error)

	// BidiStreaming initiates a bidirectional-streaming RPC call.
	// The client and server both send and receive streams of messages.
	BidiStreaming(ctx context.Context, method string) (streaming.BidiStreamingClient, error)
}

// streamClient implements StreamClient interface with endpoint middleware support.
type streamClient struct {
	kc *kClient

	// Endpoint middleware from pkg/endpoint/cep
	streamEP     cep.StreamEndpoint
	streamRecvEP cep.StreamRecvEndpoint
	streamSendEP cep.StreamSendEndpoint
}

// newStreamClient creates a new stream-aware client with endpoint middleware chains.
func newStreamClient(kc *kClient, streamMWs []cep.StreamMiddleware,
	recvMWs []cep.StreamRecvMiddleware, sendMWs []cep.StreamSendMiddleware) *streamClient {

	sc := &streamClient{kc: kc}

	// Build endpoint with middleware chains
	sc.streamEP = sc.buildStreamEndpoint(streamMWs)
	sc.streamRecvEP = sc.buildRecvEndpoint(recvMWs)
	sc.streamSendEP = sc.buildSendEndpoint(sendMWs)

	return sc
}

// buildStreamEndpoint constructs the StreamEndpoint with middleware chain.
func (sc *streamClient) buildStreamEndpoint(mws []cep.StreamMiddleware) cep.StreamEndpoint {
	// Base endpoint that establishes the stream
	base := func(ctx context.Context, stream streaming.ClientStream, req, resp interface{}) error {
		// Delegate to existing kClient streaming infrastructure
		return sc.kc.Stream(ctx, rpcinfo.GetRPCInfo(ctx).Invocation().MethodName(), req, resp)
	}

	// Apply middleware chain
	if len(mws) > 0 {
		return cep.StreamChain(mws...)(base)
	}
	return base
}

// buildRecvEndpoint constructs the StreamRecvEndpoint with middleware chain.
func (sc *streamClient) buildRecvEndpoint(mws []cep.StreamRecvMiddleware) cep.StreamRecvEndpoint {
	// Base receive endpoint
	base := func(ctx context.Context, stream streaming.ClientStream, resp interface{}) error {
		return stream.RecvMsg(resp)
	}

	// Apply middleware chain
	if len(mws) > 0 {
		return cep.StreamRecvChain(mws...)(base)
	}
	return base
}

// buildSendEndpoint constructs the StreamSendEndpoint with middleware chain.
func (sc *streamClient) buildSendEndpoint(mws []cep.StreamSendMiddleware) cep.StreamSendEndpoint {
	// Base send endpoint
	base := func(ctx context.Context, stream streaming.ClientStream, req interface{}) error {
		return stream.SendMsg(req)
	}

	// Apply middleware chain
	if len(mws) > 0 {
		return cep.StreamSendChain(mws...)(base)
	}
	return base
}

// ServerStreaming implements StreamClient.ServerStreaming.
func (sc *streamClient) ServerStreaming(ctx context.Context, method string, req interface{}) (streaming.ServerStreamingClient, error) {
	if ctx == nil {
		return nil, errors.New("ctx is nil")
	}
	if !sc.kc.inited {
		return nil, errors.New("client not initialized")
	}
	if sc.kc.closed {
		return nil, errors.New("client is already closed")
	}

	// Initialize RPC info
	ctx, ri, _ := sc.kc.initRPCInfo(ctx, method, 0, nil)
	rpcinfo.AsMutableRPCConfig(ri.Config()).SetInteractionMode(rpcinfo.Streaming)
	ctx = rpcinfo.NewCtxWithRPCInfo(ctx, ri)

	// Create response placeholder
	var resp interface{}

	// Execute through endpoint middleware
	if err := sc.streamEP(ctx, nil, req, resp); err != nil {
		return nil, err
	}

	// Wrap with generic server streaming client
	return streaming.NewServerStreamingClient(ctx, sc.streamRecvEP), nil
}

// ClientStreaming implements StreamClient.ClientStreaming.
func (sc *streamClient) ClientStreaming(ctx context.Context, method string) (streaming.ClientStreamingClient, error) {
	if ctx == nil {
		return nil, errors.New("ctx is nil")
	}
	if !sc.kc.inited {
		return nil, errors.New("client not initialized")
	}
	if sc.kc.closed {
		return nil, errors.New("client is already closed")
	}

	// Initialize RPC info
	ctx, ri, _ := sc.kc.initRPCInfo(ctx, method, 0, nil)
	rpcinfo.AsMutableRPCConfig(ri.Config()).SetInteractionMode(rpcinfo.Streaming)
	ctx = rpcinfo.NewCtxWithRPCInfo(ctx, ri)

	// Execute through endpoint middleware to establish stream
	var req, resp interface{}
	if err := sc.streamEP(ctx, nil, req, resp); err != nil {
		return nil, err
	}

	// Wrap with generic client streaming client
	return streaming.NewClientStreamingClient(ctx, sc.streamSendEP, sc.streamRecvEP), nil
}

// BidiStreaming implements StreamClient.BidiStreaming.
func (sc *streamClient) BidiStreaming(ctx context.Context, method string) (streaming.BidiStreamingClient, error) {
	if ctx == nil {
		return nil, errors.New("ctx is nil")
	}
	if !sc.kc.inited {
		return nil, errors.New("client not initialized")
	}
	if sc.kc.closed {
		return nil, errors.New("client is already closed")
	}

	// Initialize RPC info
	ctx, ri, _ := sc.kc.initRPCInfo(ctx, method, 0, nil)
	rpcinfo.AsMutableRPCConfig(ri.Config()).SetInteractionMode(rpcinfo.Streaming)
	ctx = rpcinfo.NewCtxWithRPCInfo(ctx, ri)

	// Execute through endpoint middleware to establish stream
	var req, resp interface{}
	if err := sc.streamEP(ctx, nil, req, resp); err != nil {
		return nil, err
	}

	// Wrap with generic bidirectional streaming client
	return streaming.NewBidiStreamingClient(ctx, sc.streamSendEP, sc.streamRecvEP), nil
}

// AsStreamClient converts a regular Client to a StreamClient.
// This allows existing clients to use the new streaming APIs.
func AsStreamClient(c Client, streamMWs []cep.StreamMiddleware,
	recvMWs []cep.StreamRecvMiddleware, sendMWs []cep.StreamSendMiddleware) (StreamClient, error) {

	kc, ok := c.(*kClient)
	if !ok {
		// Try unwrapping finalizer client
		if kcf, ok := c.(*kcFinalizerClient); ok {
			kc = kcf.kClient
		} else {
			return nil, errors.New("client is not a kClient instance")
		}
	}

	return newStreamClient(kc, streamMWs, recvMWs, sendMWs), nil
}

