// Dump returns diagnostic information about the connection pool state.
// Returns a map where keys are remote addresses and values are slices of connection info.
// This method is panic-safe and will log errors if any occur during the dump.
func (p *connPool) Dump() interface{} {
	result := make(map[string]interface{})

	defer func() {
		if r := recover(); r != nil {
			klog.Errorf("KITEX: panic during connection pool dump: %v", r)
		}
	}()

	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}

		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		var connInfos []interface{}
		for i := 0; i < int(trans.size); i++ {
			if trans.cliTransports[i] == nil {
				continue
			}

			connInfo := make(map[string]interface{})
			ct := trans.cliTransports[i]

			// Collect basic connection info with panic protection
			func() {
				defer func() {
					if r := recover(); r != nil {
						klog.Errorf("KITEX: panic collecting connection info for %s: %v", addr, r)
					}
				}()

				if isActive, ok := ct.(grpc.IsActive); ok {
					connInfo["active"] = isActive.IsActive()
				}

				if ct.RemoteAddr() != nil {
					connInfo["remote_addr"] = ct.RemoteAddr().String()
				}
				if ct.LocalAddr() != nil {
					connInfo["local_addr"] = ct.LocalAddr().String()
				}
			}()

			connInfos = append(connInfos, connInfo)
		}

		result[addr] = connInfos
		return true
	})

	return result
}

// newTLSConn constructs a client-side TLS connection and performs handshake.
func newTLSConn(conn net.Conn, tlsCfg *tls.Config) (net.Conn, error) {
	tlsConn := tls.Client(conn, tlsCfg)
	if err := tlsConn.Handshake(); err != nil {
		return nil, err
	}
	return tlsConn, nil
}

