// WithUnaryRPCTimeout specifies the RPC timeout for unary calls.
// This sets the maximum duration for a single unary RPC request-response cycle.
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return UnaryOption{F: func(o *client.UnaryOptions, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%s)", d))
		o.RPCTimeout = &d
	}}
}

// WithUnaryMiddleware adds middleware for unary RPC calls.
